(6775839, 1015265, 54446, '<td valign="top">Nice closeup.  This is an iconic Spring image.  It really says Spring!   Well done.  9</td>', 'Nice closeup.  This is an iconic Spring image.  It really says Spring!   Well done.  9', '2012-05-22 22:41:03.000000', NULL, 1),
(6775842, 1015662, 54446, '<td valign="top">My top pick in this challenge.  this is simply beautiful and peaceful.  Well done!  10</td>', 'My top pick in this challenge.  this is simply beautiful and peaceful.  Well done!  10', '2012-05-22 22:41:55.000000', NULL, 1),
(6775847, 1015522, 54446, '<td valign="top">The Spring lambs truly meet the challenge.  Love the monochrome.  I also think the slight motion blur of the lead lamb indicates motion.  So, nice! Bumping up to 10 on pure beauty.</td>', 'The Spring lambs truly meet the challenge.  Love the monochrome.  I also think the slight motion blur of the lead lamb indicates motion.  So, nice! Bumping up to 10 on pure beauty.', '2012-05-22 22:44:13.000000', NULL, 1),
