(7095475, 1015081, 91360, '<td valign="top">perfect</td>', 'perfect', '2013-08-30 15:43:40.000000', NULL, 0),
(7151684, 1014846, 116247, '<td valign="top">I like the DOF you have and the framing of the picture. It seems like it has been over sharpened where the curve of the orange pedal leads to the green background (lower left)</td>', 'I like the DOF you have and the framing of the picture. It seems like it has been over sharpened where the curve of the orange pedal leads to the green background (lower left)', '2014-01-04 10:41:06.000000', NULL, 0),
(7243627, 1014846, 152252, '<td valign="top">Beautiful colors. Lovely composition and DOF.</td>', 'Beautiful colors. Lovely composition and DOF.', '2014-07-23 18:04:24.000000', NULL, 0);
